namespace Math {
    class Vector {
        double x, y;
    public:
        Vector(double x, double y) : x(x), y(y) {}

        friend Vector operator+(const Vector& a, const Vector& b);
    };

    Vector operator+(const Vector& a, const Vector& b) {
        return Vector(a.x + b.x, a.y + b.y);
    }
}
